import base64, json

def send_landlord_email(to, subject, body_text):
    """Encode an RFC 2822 message as base64url and send it via Gmail messages.send."""
    raw = f"To: {to}\r\nSubject: {subject}\r\nMIME-Version: 1.0\r\nContent-Type: text/plain; charset=\"UTF-8\"\r\n\r\n{body_text}"
    enc = base64.urlsafe_b64encode(raw.encode("utf-8")).decode("ascii")
    return tools.mcp__world__api_fetch(
        url="https://gmail.googleapis.com/gmail/v1/users/me/messages/send",
        method="POST",
        body={"raw": enc},
    )

